import itertools
def solve(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    sep_rows={r for r in range(H) if len(set(g[r]))==1}
    sep_cols={c for c in range(W) if len({g[r][c] for r in range(H)})==1}
    bg=Counter(g[r][c] for r in range(H) for c in range(W) if r not in sep_rows and c not in sep_cols).most_common(1)[0][0]
    anchors={}
    for r in range(H):
        for c in range(W):
            if r not in sep_rows and c not in sep_cols and g[r][c]!=bg:
                anchors.setdefault(g[r][c],[]).append((r,c))
    out=[r[:] for r in g]
    for v,ps in anchors.items():
        ps=set(ps)
        for (r1,c1),(r2,c2) in itertools.combinations(sorted(ps),2):
            if c1==c2 and r1<r2:
                rr=r1+3
                while rr<r2:
                    if rr not in sep_rows and out[rr][c1]==bg: out[rr][c1]=v
                    rr+=3
            elif r1==r2 and c1<c2:
                cc=c1+2
                while cc<c2:
                    if cc not in sep_cols and out[r1][cc]==bg: out[r1][cc]=v
                    cc+=2
    return out
